def zigzag_star_pattern(n):
    ROWS = 4
    grid = [[' '] * n for _ in range(ROWS)]
    for c in range(n):
        m = c % 6                                # closed-form reflection, computed fresh every column
        row = m if m <= 3 else 6 - m
        grid[row][c] = '*'
    for row in grid:
        print(''.join(row))


if __name__ == "__main__":
    zigzag_star_pattern(9)

