def zigzag_star_pattern(n):
    ROWS = 4
    star_row = [0] * n
    cur, direction = 0, 1
    for c in range(n):
        star_row[c] = cur                        # O(1) work per column, no formula re-derived
        if cur == 0:
            direction = 1
        elif cur == ROWS - 1:
            direction = -1
        cur += direction
    for row in range(ROWS):
        print(''.join('*' if star_row[c] == row else ' ' for c in range(n)))


if __name__ == "__main__":
    zigzag_star_pattern(9)

