def zigzag_star_pattern(n):
    ROWS = 4
    period = 2 * (ROWS - 1)                      # 6: 3 steps down, 3 steps up
    for row in range(ROWS):
        chars = [' '] * n
        for c in range(row, n, period):
            chars[c] = '*'                          # on the way down
        if row != 0 and row != ROWS - 1:
            for c in range(period - row, n, period):
                chars[c] = '*'                      # on the way back up
        print(''.join(chars))


if __name__ == "__main__":
    zigzag_star_pattern(9)

